-- ============================================================================
--  新业务模拟模块 — 测试数据脚本 (DATA)
-- ============================================================================
--  适用数据库: MySQL 8.0+ / prcp_db
--  前置条件: 先执行 01_sim_schema.sql (建表)
--
--  数据范围:
--    prcp_sim_scheme         全部方案 (4 条)
--    prcp_sim_node_config    全部节点配置 (38 条)
--    prcp_sim_term_ratio     全部期限占比 (128 条)
--    prcp_sim_rhythm         全部 12 月节奏权重 (444 条)
--    prcp_sim_growth_config  全部增长配置 (37 条)
--    prcp_sim_run            引擎运行记录 (15 条, 含 SUCCESS/FAILED 样本)
--    prcp_sim_result         抽样 (116 条):
--                           (a) date_offset=1 全部节点   → 验证节点矩阵 / 驾驶舱 KPI 汇总
--                           (b) 节点 11 (S010201000000) 60 月 → 验证趋势 / 到期排期 / 投放分解

--  ℹ️ 数据说明: 保留 is_deleted=1 的历史行 (配置更新时「软删+插入」产生的残留),
--     引擎与所有查询均带 is_deleted=0 过滤, 不影响功能; 保留可还原真实数据状态。
--     已知: config_id=1 (scheme 6) 有 2 行软删残留, 故该 config 占比合计显示 200%,
--     有效行 (is_deleted=0) 合计为 100%。
--  ⚠️ 外键依赖: prcp_sim_scheme.coa_scheme_id → prcp_coa_scheme.id
--     需先存在 coa_scheme_id=1 (中信银行账户册方案 ZX_COA)
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


-- ============================================================================
-- 1. 新业务模拟方案 (prcp_sim_scheme)
-- 一个方案 = 一个测算场景 (账户册方案 + 基准月 + 预测月数 + 算法)
-- ============================================================================


-- ============================================================================
-- 2. 节点参数配置 (prcp_sim_node_config)
-- is_model_calc: 1=模型测算(投放) 2=存量保持(只滚桶) | rhythm_type: 1=线性 2=自定义
-- ============================================================================


-- ============================================================================
-- 3. 新业务期限占比 (prcp_sim_term_ratio)
-- term_value=期限(月) | business_ratio=业务占比(%) | interest_rate=新业务利率(%)
-- ============================================================================


-- ============================================================================
-- 4. 12 个月投放节奏权重 (prcp_sim_rhythm)
-- month_no=1~12 | weight=当月权重(%), 12 个月合计 100%
-- ============================================================================


-- ============================================================================
-- 5. 新业务增长配置 (prcp_sim_growth_config)
-- growth_type: 1=目标增长百分比 2=目标增长绝对值 3=增长百分比 4=增长值 | year1~5_value=5 年参数
-- ============================================================================


-- ============================================================================
-- 6. 引擎运行记录 (prcp_sim_run)
-- status: PENDING/RUNNING/SUCCESS/FAILED/CANCELLED | progress=0~100
-- ============================================================================


-- ============================================================================
-- 7. 引擎结果快照 (prcp_sim_result) — 抽样 (116 条)
--    (a) date_offset=1 全部节点      → 验证节点矩阵 / 驾驶舱 KPI 汇总
--    (b) 节点 11 (S010201000000) 60 月 → 验证趋势 / 到期排期 / 投放分解
--
--    128 桶 = orig_m1..orig_m60 + rem_m1..rem_m60 + orig/rem_y10/y15/y20/y30
--             (rem_* = 绝对到期月口径: 第 M 月投放期限 v → 落 rem_m{M+v})
--    7 追踪列 = growth_type / year_target / rhythm_weight / month_add /
--               month_release / planned_due / cum_planned
-- ============================================================================

SET FOREIGN_KEY_CHECKS = 1;

